window.WOLFIE_CONTEXT_PACKS=(window.WOLFIE_CONTEXT_PACKS||[]).concat([{"id":"mission-v2-006","day":6,"level":"A2","title":"Watering the neighbour's plants","ru":"Присмотреть за растениями","goal":"Попросить о помощи, уточнить периодичность и объяснить простые условия.","version":2,"quality":"authored-not-independently-reviewed","grammar":{"title":"How often / how long","rule":"How often — как часто (частота), how long — как долго (продолжительность). В вопросах с do/does смысловой глагол в начальной форме.","pattern":"How often + do/does + subject + verb?","example":"How often do I need to water this plant?","pitfall":"Не путай How long do I stay? и How often do I come?","exercises":[["choice","___ do you visit your neighbour? Twice a week.",["How often","How long","How much"],0,"Twice a week describes frequency."],["type","Complete with how long: ___ will you be away?",["how long"],"The question asks for a duration."],["order","Составь: Как часто ты проверяешь почту?",["check","you","often","How","mail","do","your"],"How often do you check your mail","How often + do + subject + verb."],["choice","Why should Mila check the drainage hole?",["To understand how excess water leaves the pot","To change the plant's colour","To measure the window"],0,"Drainage helps prevent water from collecting in the pot."],["type","Complete with schedule: Tara wrote a watering ___ for the week.",["schedule"],"A schedule records planned times."],["order","I will check the soil before I water the plant.",["I","will","check","the","soil","before","I","water","the","plant"],"I will check the soil before I water the plant","Before introduces the time clause."]]},"words":[["a watering can","лейка"],["a flowerpot","цветочный горшок"],["a sunny windowsill","солнечный подоконник"],["a spare key","запасной ключ"],["damp soil","влажная почва"],["a care label","этикетка с рекомендациями по уходу"],["a drainage hole","дренажное отверстие"],["a plant saucer","поддон для цветочного горшка"],["a watering schedule","график полива"],["a house-sitter","человек, присматривающий за домом"]],"phrases":[["Could you look after my plants while I'm away?","Можешь присмотреть за моими растениями, пока меня не будет?"],["How often should I come round?","Как часто мне нужно заходить?"],["The spare key is in the envelope.","Запасной ключ лежит в конверте."],["This plant needs less water than the others.","Этому растению нужно меньше воды, чем остальным."],["I'll send you a photo if something looks unusual.","Я пришлю тебе фотографию, если что-нибудь будет выглядеть необычно."],["Check the top layer of soil before adding more water.","Проверь верхний слой почвы, прежде чем добавлять воду."],["Please keep the plant away from direct afternoon sunlight.","Пожалуйста, убери растение от прямого послеполуденного солнца."],["I'll send you an update after each visit.","Я буду отправлять тебе сообщение после каждого визита."],["Could you show me which leaves should be removed?","Можешь показать, какие листья нужно удалить?"],["Let's agree on a time when I can collect the spare key.","Давай договоримся, когда я смогу забрать запасной ключ."]],"reading":{"title":"Watering the neighbour's plants","paragraphs":["Tara is going away for a week and asks Mila to look after the plants in her flat. She leaves a spare key in an envelope and puts a small care label beside each flowerpot. Mila asks how often she should visit, because she has work on most mornings. Tara says that two visits will be enough for these particular plants.","On her first visit, Mila notices that the soil in one pot is still damp. She reads the label and decides not to water that plant yet. She sends Tara a photo to check. Tara thanks her for asking instead of guessing. When she returns home, she collects the key and invites Mila for tea.","Before leaving, Tara shows Mila the drainage holes and explains which plants need a dry surface. Mila writes the watering schedule on her phone, but she knows the note is only a reminder; she should still check the soil. This prevents her from following the schedule blindly when the weather is cooler."],"questions":[["How long will Tara be away?",["A week","Two months","One afternoon"],0],["Why does Mila skip watering one plant?",["The pot is empty","The soil is still damp","She lost the key"],1],["How does Mila check her decision?",["She asks a stranger","She buys a new plant","She sends Tara a photo"],2],["What does Mila do before leaving?",["She buys new flowerpots","She learns which plants need a dry surface","She changes the spare key"],1]]},"dialogue":[["Tara","Could you look after my plants next week?","Можешь присмотреть за моими растениями на следующей неделе?"],["Mila","Of course. How often should I visit?","Конечно. Как часто мне нужно заходить?"],["Tara","Twice will be enough. I've left a note by each pot.","Двух раз будет достаточно. Я оставила записку у каждого горшка."],["Mila","Great. I'll message you if I have a question.","Отлично. Напишу тебе, если возникнет вопрос."],["Tara","This plant has a drainage hole under the pot.","У этого растения есть дренажное отверстие под горшком."],["Mila","Should I empty the plant saucer after watering?","Мне нужно опорожнять поддон после полива?"],["Tara","Yes, if water collects there. Please check the soil first.","Да, если там скапливается вода. Сначала проверь почву."],["Mila","I'll follow the notes and send you an update.","Я буду следовать записям и отправлю тебе сообщение."]],"listening":["How many visits does Tara suggest?",["One","Two","Seven"],1],"speaking":["Ask a neighbour to look after something while you are away.","Ask three questions about the frequency of household tasks.","Explain where a visitor can find a spare key without mentioning a real address.","Describe the difference between two fictional plants.","Tell Tara what you noticed during your visit and ask for advice."],"writing":["Write a short care note for a friend visiting your flat.","Reply to a neighbour who asks you to look after their plants.","Write a message asking whether a fictional plant needs water."],"model":"Hi Mila, thanks for helping. Please visit on Tuesday and Friday. The key is in the envelope. Read the labels before watering the plants. Send me a message if you have any questions.","profile":"extended-v1"},{"id":"mission-v2-036","day":36,"level":"A2","title":"The ferry timetable","ru":"Паромное расписание","goal":"Уточнить время отправления, стоимость и запасной вариант маршрута.","version":2,"quality":"authored-not-independently-reviewed","grammar":{"title":"Present Simple for timetables","rule":"Present Simple описывает установленное расписание, даже если событие произойдёт в будущем. Для договорённости о личной встрече часто подходит Present Continuous.","pattern":"The ferry leaves at nine. / We are meeting at eight.","example":"The next ferry leaves at half past ten.","pitfall":"Не добавляй -s к глаголу после does.","exercises":[["choice","The last ferry ___ at six this evening.",["leave","leaves","leaving"],1,"Present Simple for the timetable; third person singular takes -s."],["type","Complete: What time ___ (the train / leave)? Use Present Simple.",["does the train leave"],"Does + subject + base form."],["order","Составь: Поезд отправляется в восемь.",["eight","train","leaves","The","at"],"The train leaves at eight","Present Simple for a scheduled departure."],["choice","The first boat ___ from pier two on weekdays.",["sail","sails","is sail"],1,"The first boat sails."],["type","Complete: What time ___ (boarding / close) on Sundays?",["does boarding close"],"Does + subject + base form."],["order","Скажи: последний рейс отправляется в семь.",["seven","at","leaves","sailing","last","The"],"The last sailing leaves at seven","Present Simple for schedules."]]},"words":[["a ferry terminal","паромный терминал"],["a return ticket","билет туда и обратно"],["a boarding gate","выход на посадку"],["a sailing time","время отправления судна"],["a foot passenger","пеший пассажир"],["a timetable change","изменение расписания"],["a seasonal ferry schedule","сезонное расписание парома"],["an outbound sailing","рейс в прямом направлении"],["a last return sailing","последний обратный рейс"],["a boarding announcement","объявление о посадке"]],"phrases":[["What time does the next ferry leave?","Во сколько отправляется следующий паром?"],["Is this ticket valid for the return journey?","Этот билет действует на обратную поездку?"],["Where do foot passengers board?","Где садятся пешие пассажиры?"],["The timetable is different on Sundays.","По воскресеньям расписание другое."],["We can take the later ferry if necessary.","При необходимости мы можем сесть на более поздний паром."],["The old noticeboard shows the summer service only.","На старом стенде указано только летнее расписание."],["Does the return sailing leave from the same pier?","Обратный рейс отправляется с того же причала?"],["Boarding closes five minutes before the boat leaves.","Посадка заканчивается за пять минут до отправления судна."],["We are meeting our friends on the other side of the river.","Мы встречаемся с друзьями на другом берегу реки."],["Let's allow enough time to catch the last ferry back.","Давай оставим достаточно времени, чтобы успеть на последний обратный паром."]],"reading":{"title":"The ferry timetable","paragraphs":["Ben and Mila plan a day trip across the river. They arrive at the ferry terminal at nine, but the boat they expected to take does not run on Sundays. Ben finds a summer timetable on an old noticeboard. Mila checks the current timetable at the ticket desk and learns that the next ferry leaves at half past ten.","They buy return tickets and ask where foot passengers board. Instead of waiting beside the gate for ninety minutes, they visit a nearby café. The ticket seller tells them when to return for boarding. Later, they check the last ferry back before making plans on the other side of the river.","At the café they write down the departure and return times. The last return sailing leaves at seven in the evening, so they decide to finish their walk by six. Mila also checks the pier number because the return boat uses a different pier."],"questions":[["Why do they miss the expected ferry?",["It is full","It does not run on Sundays","They lose their tickets"],1],["When does the next ferry leave?",["Half past ten","Nine","Noon"],0],["What do they check before making more plans?",["The café menu","The price of a car","The last return ferry"],2],["Why does Mila check the pier number?",["The return boat uses a different pier","They are taking a train","The café is on the boat"],0]]},"dialogue":[["Ben","Does the nine o'clock ferry run today?","Девятичасовой паром сегодня ходит?"],["Seller","Not on Sundays. The next one leaves at ten thirty.","По воскресеньям нет. Следующий отправляется в десять тридцать."],["Ben","Can I buy two return tickets, please?","Можно два билета туда и обратно?"],["Seller","Certainly. Boarding starts fifteen minutes before departure.","Конечно. Посадка начинается за пятнадцать минут до отправления."],["Ben","Does the return boat leave from this pier too?","Обратный паром тоже отправляется с этого причала?"],["Seller","No, it leaves from pier three on the other side.","Нет, с третьего причала на другом берегу."],["Ben","What time does the last return sailing leave?","Во сколько отправляется последний обратный рейс?"],["Seller","At seven. Please arrive before boarding closes.","В семь. Пожалуйста, приходите до окончания посадки."]],"listening":["When does boarding start?",["Fifteen minutes before departure","An hour after departure","At nine every day"],0],"speaking":["Ask a ticket seller about the first and last departure of the day.","Explain a timetable change to your travel companion.","Compare a one-way ticket with a return ticket.","Plan a short trip using two fictional departure times.","Ask where passengers without a car should wait."],"writing":["Write a message telling a friend about a changed departure time.","Create a short travel plan with outward and return times.","Write three questions to a ferry operator about Sunday services."],"model":"Hi Ben, the nine o'clock ferry doesn't run on Sunday. The next one leaves at ten thirty. Let's meet at the terminal at ten and buy return tickets.","profile":"extended-v1"},{"id":"mission-v2-066","day":66,"level":"A2","title":"A difficult invitation","ru":"Отказ без обиды","goal":"Вежливо отклонить приглашение, выразить желание и предложить другой вариант.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Would rather + base verb","rule":"Would rather + глагол без to выражает предпочтение. Отрицание: would rather not + глагол. Для выбора: I'd rather stay home than go out.","pattern":"I'd rather + base verb; I'd rather not + base verb","example":"I'd rather meet tomorrow than go out tonight.","pitfall":"Не говори I'd rather to stay.","exercises":[["choice","I'd rather ___ at home tonight.",["staying","to stay","stay"],2,"Would rather takes a bare infinitive."],["type","Complete: I'd rather ___ (not / go) out today.",["not go"],"Would rather not + base verb."],["order","Составь: Я предпочёл бы встретиться завтра.",["rather","tomorrow","would","meet","I"],"I would rather meet tomorrow","Would rather + bare infinitive."]]},"words":[["a personal commitment","личное обязательство"],["a quiet night in","спокойный вечер дома"],["a last-minute invitation","приглашение в последний момент"],["an alternative date","другая дата"],["a polite refusal","вежливый отказ"],["to take it personally","принимать на свой счёт"]],"phrases":[["Thanks for thinking of me.","Спасибо, что подумал обо мне."],["I'd rather have a quiet evening tonight.","Сегодня вечером я предпочёл бы отдохнуть дома."],["It's nothing to do with you.","Это не связано с тобой."],["Could we do something together on Saturday?","Можем вместе заняться чем-нибудь в субботу?"],["I understand if tonight doesn't work for you.","Я понимаю, если сегодня вечером тебе неудобно."]],"reading":{"title":"A difficult invitation","paragraphs":["Alex invites Mila to a busy party on Friday evening. Mila has had a long week and would rather stay at home. At first, she worries that Alex may think she does not enjoy his company. She decides to thank him for the invitation and explain her preference honestly. She suggests a walk on Saturday instead.","Alex replies that he understands and says he can go to the party with another friend. He also likes the idea of a walk the next day. Mila feels relieved because she has not made an excuse or agreed to a plan she does not want. The two friends agree that a refusal does not always mean a lack of interest."],"questions":[["Why does Mila prefer to stay home?",["She has had a long week","She dislikes Alex","She has lost her phone"],0],["What does she suggest instead?",["A different party tonight","A walk on Saturday","No future meeting"],1],["How does Alex respond?",["He insists she attend","He stops replying","He understands and accepts the alternative"],2]]},"dialogue":[["Alex","Would you like to come to a party tonight?","Хочешь пойти сегодня на вечеринку?"],["Mila","Thanks! I'd rather stay home this evening.","Спасибо! Сегодня вечером я предпочла бы остаться дома."],["Alex","No problem. What about the weekend?","Без проблем. А как насчёт выходных?"],["Mila","I'd love to go for a walk on Saturday.","Я с удовольствием прогуляюсь в субботу."]],"listening":["What does Mila want to do on Saturday?",["Go for a walk","Work late","Host a party"],0],"speaking":["Decline a late invitation while showing that you appreciate it.","Explain which evening activity you prefer and why.","Offer two alternatives to a plan you cannot accept.","Respond to a friend's refusal without taking it personally.","Role-play an honest conversation about different weekend preferences."],"writing":["Write a friendly refusal of an invitation with a specific alternative.","Write a reply accepting a friend's decision and offering another date.","Describe your ideal quiet evening and compare it with a busy party."],"model":"Thanks for inviting me! I'd rather stay in tonight because I'm tired. I'd love to see you on Saturday, though. Would you like to go for a walk?"},{"id":"mission-v2-096","day":96,"level":"A2","title":"A wallet at the cinema","ru":"Бумажник в кинотеатре","goal":"Объяснить, где и когда потерян предмет, и уточнить его приметы.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"There was / there were","rule":"There was употребляется с единственным числом и неисчисляемыми существительными; there were — с множественным. Вопрос: Was there…? Were there…?","pattern":"There was a wallet. There were two cards.","example":"There were two tickets inside the wallet.","pitfall":"Не говори there was two tickets.","exercises":[["choice","There ___ two tickets inside.",["was","were","is"],1,"Two tickets is plural."],["type","Complete: There ___ a key in the bag yesterday.",["was"],"A key is singular and yesterday is past."],["order","Составь: В кармане был телефон.",["phone","the","was","There","in","pocket","a"],"There was a phone in the pocket","There was + singular noun."]]},"words":[["a lost-property desk","стойка находок"],["a leather wallet","кожаный бумажник"],["a ticket stub","корешок билета"],["a seat number","номер места"],["a distinguishing mark","отличительный признак"],["a claim form","бланк обращения"]],"phrases":[["I think I left my wallet in the cinema.","Кажется, я оставил бумажник в кинотеатре."],["There were two cinema tickets inside it.","Внутри было два билета в кино."],["Could you check whether anyone handed it in?","Не могли бы вы проверить, не сдал ли кто-нибудь его в бюро находок?"],["It has a small scratch near the zip.","Возле молнии есть небольшая царапина."],["I'll bring identification when I collect it.","Я принесу удостоверение личности, когда буду забирать его."]],"reading":{"title":"A wallet at the cinema","paragraphs":["After watching a film, Ben discovers that his wallet is missing. He remembers paying for popcorn before the film and putting the wallet in his coat pocket. At home, he checks the coat again but finds only his phone. He calls the cinema and explains where he sat and what the wallet looks like.","The employee says that a member of staff found a wallet after the evening screening. Ben describes a small scratch near the zip and says there were two cinema tickets inside. The employee asks him to visit the lost-property desk with identification. Ben agrees to collect it the following afternoon. He is pleased that somebody handed it in."],"questions":[["Where does Ben think he lost the wallet?",["At a bus station","At the cinema","At work"],1],["What detail helps identify it?",["A scratch near the zip","A large red ribbon","A broken handle"],0],["What should Ben bring?",["A new wallet","Popcorn","Identification"],2]]},"dialogue":[["Ben","Has anyone handed in a wallet from screen three?","Кто-нибудь сдавал бумажник из третьего зала?"],["Employee","We found one after the last film. Can you describe it?","Мы нашли один после последнего фильма. Можете его описать?"],["Ben","It's brown leather, with a scratch near the zip.","Он коричневый, кожаный, с царапиной возле молнии."],["Employee","Please visit the lost-property desk with identification.","Пожалуйста, подойдите к стойке находок с удостоверением личности."]],"listening":["What colour is the wallet?",["Black","Brown","Blue"],1],"speaking":["Describe a fictional lost object in enough detail to identify it.","Ask a cinema employee about something left after a film.","Reconstruct the last three places you used a fictional wallet.","Explain which information should be shared privately rather than posted publicly.","Thank someone who returned a missing item."],"writing":["Write a lost-property enquiry describing a fictional object and its last known location.","Write a brief message to a friend explaining that you found a missing wallet.","Write a reply from a lost-property desk explaining how to collect an item."],"model":"Hello, I may have left a brown wallet in screen three yesterday evening. There were two cinema tickets inside it. Could you check your lost-property desk? Thank you."},{"id":"mission-v2-126","day":126,"level":"B1","title":"Feedback after a training session","ru":"Обратная связь после обучения","goal":"Принимать конкретную обратную связь, уточнять критерии и договариваться о дальнейшем развитии.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Used to / be used to","rule":"Used to + verb описывает прежнюю привычку, которая изменилась. Be used to + noun/-ing означает «быть привыкшим». Get used to — постепенно привыкать.","pattern":"used to explain; am used to explaining","example":"I used to speak too quickly, but now I'm used to checking understanding.","pitfall":"Не путай I used to speaking и I am used to speak.","exercises":[["choice","I ___ speak too quickly, but I have changed.",["am used to","used to","use to speaking"],1,"Used to + base verb describes a past habit."],["type","Complete: She is used to ___ (teach) small groups.",["teaching"],"Be used to + -ing."],["order","Составь: Я привык задавать вопросы.",["used","questions","am","asking","I","to"],"I am used to asking questions","Be used to + gerund."]]},"words":[["a feedback session","обсуждение обратной связи"],["a learning objective","учебная цель"],["an assessment criterion","критерий оценки"],["a practical demonstration","практическая демонстрация"],["a constructive comment","конструктивное замечание"],["an improvement target","цель улучшения"]],"phrases":[["Could you give me a specific example?","Не могли бы вы привести конкретный пример?"],["I used to explain everything at once.","Раньше я объяснял всё сразу."],["I'm getting used to asking learners for feedback.","Я постепенно привыкаю спрашивать учеников об обратной связи."],["The objective is clear, but the explanation needs more structure.","Цель ясна, но объяснение нужно лучше структурировать."],["Let's review my next session against the same criteria.","Давайте оценим моё следующее занятие по тем же критериям."]],"reading":{"title":"Feedback after a training session","paragraphs":["Ben delivers a short workplace training session for new employees. He knows the topic well and explains several procedures, but his colleague notices that the learners have few chances to ask questions. After the session, she gives him feedback: the examples are relevant, yet the order of information is difficult to follow.","Ben asks for a specific example instead of defending every detail. His colleague suggests dividing the explanation into smaller steps and checking understanding after each one. Ben used to think that a good trainer should speak without interruption. He now recognises that questions can reveal misunderstandings. They agree to review his next session against the same criteria, including clarity, relevance and opportunities for practice."],"questions":[["What does the colleague criticise?",["The order of information and limited questions","The room temperature","Ben's attendance"],0],["What does Ben ask for?",["An immediate promotion","A specific example","A different trainer"],1],["How will they review the next session?",["Without any criteria","Only by counting minutes","Against the same criteria"],2]]},"dialogue":[["Colleague","Your examples were useful, but the learners needed more time to ask questions.","Примеры были полезными, но ученикам требовалось больше времени для вопросов."],["Ben","Could you give me a specific example?","Не могли бы вы привести конкретный пример?"],["Colleague","After the second explanation, two people looked confused.","После второго объяснения двое выглядели растерянными."],["Ben","I'll add a short practice task at that point next time.","В следующий раз я добавлю в этом месте короткое практическое задание."]],"listening":["What will Ben add?",["A longer introduction","A short practice task","A new room"],1],"speaking":["Ask a trainer for feedback on a particular part of a lesson.","Describe a work habit you used to have and how it changed.","Explain why a specific example is more useful than a vague criticism.","Role-play receiving feedback that you only partly agree with.","Set one measurable target for improving a future explanation."],"writing":["Write a reflection on a fictional training session using used to and be used to.","Write an email requesting focused feedback on a presentation.","Draft a short improvement plan with a criterion and a review date."],"model":"I used to give long explanations without checking understanding. During the next session, I will divide the material into smaller steps and include a practice task. I would like feedback on whether the learners can explain the main idea afterwards."},{"id":"mission-v2-156","day":156,"level":"B1","title":"The rumour at the railway café","ru":"Слух в привокзальном кафе","goal":"Передавать услышанное сообщение, различать источник информации и подтверждённый факт.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Say / tell in reported speech","rule":"Say + (that) clause; tell + person + (that) clause. При переносе в прошлое возможен backshift, если контекст этого требует.","pattern":"She said that…; She told me that…","example":"A passenger told Ben that the station was closing.","pitfall":"Не говори she told that без адресата в этой конструкции.","exercises":[["choice","She ___ me that platform two was closed.",["said","told","says to"],1,"Tell requires the person as its object."],["type","Complete with say or tell in the past: He ___ that the train was late.",["said"],"Say can introduce the clause directly."],["order","Составь: Она сказала мне, что поезд задерживается.",["told","late","train","She","was","that","the","me"],"She told me that the train was late","Told + recipient + clause."]]},"words":[["an unconfirmed rumour","неподтверждённый слух"],["a noticeboard announcement","объявление на доске"],["a reliable source","надёжный источник"],["a temporary closure","временное закрытие"],["a mistaken report","ошибочное сообщение"],["a public information desk","стойка справочной информации"]],"phrases":[["Where did you hear that?","Откуда ты это услышал?"],["He said that the station might close early.","Он сказал, что вокзал, возможно, закроется раньше."],["The information hasn't been confirmed yet.","Информация пока не подтверждена."],["The official notice refers to a different platform.","Официальное объявление относится к другой платформе."],["Let's check before passing the message on.","Давай проверим, прежде чем передавать сообщение дальше."]],"reading":{"title":"The rumour at the railway café","paragraphs":["While waiting for a train, Ben hears two passengers discussing a possible station closure. One passenger says that a friend has read about it online. Another tells Ben that all evening trains have been cancelled. Ben is concerned because he needs to get home, but he notices that the departures board still shows several trains.","At the information desk, he learns that only one platform is temporarily closed for maintenance. The remaining platforms are operating normally, and the staff member shows him the official notice. Ben tells the other passengers what the notice actually says and explains that he has not checked every individual train. The group agrees to consult the departures board rather than repeat the more dramatic version of the story."],"questions":[["What was the original rumour?",["The café was moving","The station might close","The ticket price was falling"],1],["What does the official notice confirm?",["One platform is temporarily closed","All evening trains are cancelled","The station will close permanently"],0],["What does Ben avoid claiming?",["That he visited the desk","That the notice exists","That every individual train has been checked"],2]]},"dialogue":[["Passenger","Someone told me that all the trains were cancelled.","Кто-то сказал мне, что все поезда отменены."],["Ben","Did you see an official announcement?","Ты видел официальное объявление?"],["Passenger","No, I heard it from another passenger.","Нет, я услышал это от другого пассажира."],["Ben","Let's ask at the information desk before we change our plans.","Давай спросим в справочной, прежде чем менять планы."]],"listening":["Where did the passenger hear the information?",["From an official website","From another passenger","From the train driver directly"],1],"speaking":["Report a rumour using a clear attribution to its source.","Ask a person how they learned about a service disruption.","Retell the café incident without presenting the rumour as a fact.","Explain how two people can misunderstand the same notice.","Give a short update that includes one confirmed fact and one unresolved question."],"writing":["Write a message correcting a fictional rumour about a transport service.","Write a news-style paragraph separating a claim from a verified notice.","Write a dialogue in which two friends check conflicting information."],"model":"A passenger told me that all trains had been cancelled, but the official notice says that only one platform is closed. I haven't checked every departure. Please consult the current departures board."},{"id":"mission-v2-186","day":186,"level":"B1","title":"The repair café","ru":"Мастерская совместного ремонта","goal":"Объяснить условия участия, распределить обязанности и предложить разумный способ сотрудничества.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"First conditional with if","rule":"If + Present Simple, will/can/may + base verb describes a real future possibility. В обычном условном придаточном не ставят will.","pattern":"If you bring the broken lamp, we can look at it together.","example":"If the volunteer is available, we'll ask for help.","pitfall":"Не говори If you will bring it в обычном условии.","exercises":[["choice","If we have a free slot, we ___ contact you.",["will","will to","are will"],0,"First conditional: if + present, will + base."],["type","Complete: If the volunteer ___ (be) available, we can ask a question.",["is"],"The if-clause uses Present Simple."],["order","Составь: Если ты запишешься сегодня, мы подтвердим время.",["we","book","the","will","If","time","confirm","you","today"],"If you book today we will confirm the time","If + Present Simple, will + base form."]]},"words":[["a repair café","общественная мастерская ремонта"],["a volunteer organiser","организатор-волонтёр"],["a spare part","запасная деталь"],["a booking form","форма записи"],["a repairable item","предмет, пригодный к ремонту"],["a waiting list","лист ожидания"]],"phrases":[["If you book a slot, we'll reserve a place for you.","Если запишешься на время, мы зарезервируем место."],["Could you describe the problem on the form?","Можешь описать проблему в форме?"],["We can't guarantee that every item can be repaired.","Мы не можем гарантировать, что каждый предмет удастся отремонтировать."],["The volunteers will explain what they can help with.","Волонтёры объяснят, с чем они могут помочь."],["Let's give priority to items we can assess safely.","Давайте отдавать приоритет предметам, которые можно безопасно оценить."]],"reading":{"title":"The repair café","paragraphs":["A community centre organises a repair café where residents can bring everyday objects and learn about repair options. The organisers receive more requests than they expected, so they introduce a booking form. Visitors describe the item and its problem before arriving. The volunteers then decide whether they have appropriate expertise and facilities for that request.","Some visitors assume that every item will be repaired on the same day. The organisers change the invitation to explain that the event offers an assessment and possible help, not a guaranteed repair. They also set up a waiting list for future sessions. By explaining the conditions clearly, they reduce misunderstandings and give residents a better idea of what to expect. This story concerns communication, not instructions for repairing equipment."],"questions":[["Why is a booking form introduced?",["There are more requests than expected","Nobody wants help","The centre has closed"],0],["What do volunteers assess before accepting a request?",["The visitor's income","Whether they have appropriate expertise and facilities","The colour of the booking form"],1],["What does the revised invitation avoid promising?",["A description of the event","A future waiting list","A guaranteed repair"],2]]},"dialogue":[["Visitor","If I bring this broken item, will you fix it today?","Если я принесу этот сломанный предмет, вы почините его сегодня?"],["Organiser","We can assess your request, but we can't promise a repair.","Мы можем оценить вашу заявку, но не можем обещать ремонт."],["Visitor","What information do you need before I book?","Какие сведения вам нужны, прежде чем я запишусь?"],["Organiser","Please describe the item and the problem on the form.","Пожалуйста, опишите предмет и проблему в форме."]],"listening":["What does the organiser promise?",["A guaranteed repair","An assessment of the request","A free replacement"],1],"speaking":["Explain the purpose of a community repair café to a new visitor.","Describe what information would help an organiser assess a request.","Offer a conditional arrangement when all places are booked.","Explain the difference between offering help and guaranteeing a result.","Negotiate a fair way to organise a waiting list."],"writing":["Write a community announcement explaining how to book a repair-café visit.","Write a reply to a resident whose item cannot be accepted at the next session.","Draft a short evaluation of the booking process and suggest one improvement."],"model":"If you would like to attend, please complete the booking form and describe your item. The organisers will confirm whether appropriate help is available. A booking is not a guarantee of a successful repair."},{"id":"mission-v2-216","day":216,"level":"B2","title":"The exhibition without captions","ru":"Выставка без пояснений","goal":"Аргументировать доступность информации, сравнивать способы представления материала.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Cleft sentences with what","rule":"What + clause + be + focus выделяет ключевую часть мысли. После what-clause обычно употребляется is/was при единственном смысловом фокусе; возможны другие формы согласования по контексту.","pattern":"What visitors need is a clear explanation.","example":"What the survey revealed was a gap in accessibility.","pitfall":"Не путай вопрос What do visitors need? с утверждением What visitors need is…","exercises":[["choice","What the visitors need ___ a concise explanation.",["are","is","do"],1,"The focused noun phrase is singular."],["type","Complete with what: ___ surprised the curator was the range of visitor needs.",["what"],"A what-cleft foregrounds the key information."],["order","Составь: Нам нужна ясная подпись.",["a","What","caption","is","clear","we","need"],"What we need is a clear caption","What-clause + is + focus."]]},"words":[["an accessible caption","доступная пояснительная подпись"],["an audio description","аудиоописание"],["a visitor experience","впечатление посетителя"],["an interpretive panel","информационная панель"],["a language barrier","языковой барьер"],["an inclusive design","инклюзивный дизайн"]],"phrases":[["What visitors need is a way to understand the context.","Посетителям прежде всего нужен способ понять контекст."],["The same information can be presented in several formats.","Одну и ту же информацию можно представить в нескольких форматах."],["Accessibility should not depend solely on a smartphone.","Доступность не должна зависеть исключительно от смартфона."],["A concise caption may be more helpful than an extensive explanation.","Краткая подпись может быть полезнее обширного объяснения."],["We should evaluate the options with different visitor groups.","Следует оценить варианты с разными группами посетителей."]],"reading":{"title":"The exhibition without captions","paragraphs":["A museum opens an exhibition of historical photographs with very few captions. The curator wants visitors to interpret the images independently. Some visitors appreciate the open format, but others say they cannot understand the historical context, particularly when they are unfamiliar with the city or its language. A proposed mobile guide offers more information, but it does not help visitors who cannot use a smartphone comfortably.","The museum therefore tests a combination of concise printed captions, optional audio descriptions and a more detailed guide. The curator retains space for personal interpretation while making basic contextual information available. The team interviews visitors with different backgrounds and compares their ability to explain what the exhibition is about. The evaluation does not assume that one format will suit everyone. What matters is whether visitors can choose a suitable way to access the essential information."],"questions":[["Why is the mobile guide insufficient on its own?",["Some visitors cannot comfortably use smartphones","The exhibition has no photographs","Every visitor wants a mobile guide"],0],["What approach does the museum test?",["Remove all interpretation","Combine several optional formats","Require every visitor to read a long guide"],1],["What is the evaluation intended to establish?",["Whether captions are always unnecessary","Whether one visitor group likes the curator","Whether different visitors can access essential information"],2]]},"dialogue":[["Curator","I don't want captions to dictate a single interpretation.","Я не хочу, чтобы подписи навязывали одну интерпретацию."],["Visitor adviser","What some visitors need is basic context, not a prescribed opinion.","Некоторым посетителям нужен базовый контекст, а не навязанное мнение."],["Curator","Could we keep the captions short and offer optional details?","Можем оставить подписи краткими и предложить дополнительные сведения по желанию?"],["Visitor adviser","Yes. Let's compare how different visitors use each format.","Да. Давайте сравним, как разные посетители используют каждый формат."]],"listening":["What does the adviser suggest comparing?",["Ticket prices only","How visitors use each format","The number of cameras"],1],"speaking":["Explain the difference between providing context and imposing an interpretation.","Defend short printed captions while acknowledging the value of audio.","Argue against a smartphone-only solution without dismissing technology.","Describe how you would measure visitor understanding across different groups.","Present a recommendation using a what-cleft to emphasise your central point."],"writing":["Write a balanced recommendation for accessible exhibition information.","Draft a visitor-feedback questionnaire with four distinct evaluation questions.","Write an argument about preserving artistic freedom while improving access to context."],"model":"What the exhibition needs is a flexible way to provide context. Concise captions could establish essential facts, while optional audio and extended guides would support visitors who want more detail. The approach should be evaluated with different visitor groups."},{"id":"mission-v2-246","day":246,"level":"B2","title":"A GOOSE subscription question","ru":"GOOSE: уточнение подписки в проектной документации","goal":"Уточнять назначение сообщений IEC 61850 и формулировать замечания к документации без вмешательства в оборудование.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Participle clauses for background","rule":"Present participle (-ing) может сокращать придаточное, если его логический субъект совпадает с субъектом главной части. Past participle выражает пассивный смысл. Не допускай dangling participle.","pattern":"Reviewing the document, the engineer noticed a discrepancy.","example":"Based on the supplied description, the conclusion remains provisional.","pitfall":"Не говори Reviewing the file, the discrepancy appeared: файл проверяет инженер, не расхождение.","exercises":[["choice","Which sentence has a clear logical subject?",["Reviewing the file, the discrepancy appeared.","Reviewing the file, the engineer noticed a discrepancy.","Reviewing the file, the network was a document."],1,"The engineer performs the reviewing."],["type","Complete with the -ing form: ___ (compare) the two references, the reviewer noticed a difference.",["comparing"],"The reviewer performs both actions."],["order","Составь: Проверяя отчёт, мы заметили расхождение.",["noticed","the","Reviewing","we","report","a","discrepancy"],"Reviewing the report we noticed a discrepancy","The subject we performs the review; use a comma in prose."]]},"words":[["a GOOSE publisher","издатель сообщений GOOSE"],["a GOOSE subscriber","подписчик сообщений GOOSE"],["a Substation Configuration Description file","файл описания конфигурации подстанции SCD"],["an intelligent electronic device","интеллектуальное электронное устройство IED"],["a communication interface","интерфейс связи"],["a functional test report","отчёт о функциональных испытаниях"]],"phrases":[["The supplied description does not identify the intended subscriber.","В предоставленном описании не указан предполагаемый подписчик."],["Reviewing the document, we noticed an unresolved reference.","При проверке документа мы заметили неуточнённую ссылку."],["Could you clarify the intended communication relationship?","Не могли бы вы уточнить предполагаемую связь между устройствами?"],["A document reference alone does not establish operational behaviour.","Одна ссылка в документации не подтверждает поведение оборудования в эксплуатации."],["The comment concerns documentation completeness, not a configuration change.","Замечание касается полноты документации, а не изменения конфигурации."]],"reading":{"title":"A GOOSE subscription question","paragraphs":["A fictional substation automation project uses IEC 61850 terminology in its communication documentation. During a review of a GOOSE description, a specialist finds that the publisher is identified, but the intended subscriber reference is unclear. The supplied SCD file and a separate functional test report are listed in the document register. The reviewer has not established that they describe the same approved revision.","Reviewing the documents, she prepares a request for the document owner to identify the relevant references and clarify the intended communication relationship. She does not infer a confirmed communication fault from the incomplete description. The team records the question as an open documentation comment, separate from any engineering change or operational decision. The exercise develops language for discussing IEC 61850 project records; it gives no instructions for modifying GOOSE subscriptions, testing live equipment or changing protection logic."],"questions":[["Which reference is unclear?",["The intended subscriber","The building address","The document author's surname"],0],["What does the reviewer request?",["A change to protection logic","Clarification of document references and the intended relationship","A live network test"],1],["What is the scope of the open comment?",["A confirmed operational fault","An instruction to change subscriptions","A documentation question"],2]]},"dialogue":[["Reviewer","The GOOSE description identifies the publisher, but the subscriber reference is unclear.","Описание GOOSE указывает издателя, но ссылка на подписчика неясна."],["Specialist","Do we know whether the report refers to the same revision?","Известно ли нам, относится ли отчёт к той же редакции?"],["Reviewer","Not yet. Could you clarify the intended relationship and document references?","Пока нет. Не могли бы вы уточнить предполагаемую связь и ссылки на документы?"],["Specialist","I'll record the question and contact the document owner.","Я зафиксирую вопрос и свяжусь с владельцем документа."]],"listening":["What will the specialist do?",["Change a subscription","Record the question and contact the owner","Confirm an operational fault immediately"],1],"speaking":["Explain in English what a publisher and subscriber represent in the fictional documentation context.","Request clarification of an intended communication relationship without asserting an operational fault.","Summarise the difference between an SCD reference and evidence from a functional test report.","Rephrase an ambiguous document-review sentence using a participle clause with a clear subject.","Give a technical update that names the unresolved question and limits the scope of the conclusion."],"writing":["Write a fictional GOOSE documentation comment identifying the unclear subscriber reference and requesting clarification.","Draft an email asking whether two IEC 61850 document references belong to the same approved revision.","Write a technical meeting note separating documentation observations from unverified operational behaviour."],"model":"Reviewing the supplied GOOSE description, we noticed that the intended subscriber reference is unclear. Please confirm which SCD revision and functional test report apply. The comment remains open pending clarification and does not authorise a configuration change."},{"id":"mission-v2-276","day":276,"level":"B2","title":"The confident answer with no evidence","ru":"Уверенный ответ без доказательств","goal":"Проверять основания AI-ответа, объяснять ограничения и формулировать корректный запрос на проверку.","version":1,"quality":"authored-not-independently-reviewed","grammar":{"title":"Third conditional for alternative past outcomes","rule":"If + Past Perfect, would/could/might have + V3 описывает нереализованное прошлое. Could/might подчёркивают возможность, а не гарантированный результат.","pattern":"If we had checked the reference, we might have found the error earlier.","example":"If the citation had been verified, the mistake might have been noticed.","pitfall":"Не используй would have в обычном if-clause третьего условного.","exercises":[["choice","If we ___ the source, we might have found the mistake.",["would check","had checked","have checked"],1,"Third conditional uses Past Perfect in the if-clause."],["type","Complete: If she had seen the report, she might ___ (notice) the gap. Use modal perfect.",["have noticed"],"Might have + past participle."],["order","Составь: Если бы мы проверили, мы могли бы заметить ошибку.",["checked","If","noticed","we","might","the","had","have","we","error"],"If we had checked we might have noticed the error","Past perfect condition + modal perfect result."]]},"words":[["an unsupported citation","неподтверждённая ссылка"],["a fabricated reference","выдуманная ссылка"],["a verification step","этап проверки"],["a confidence signal","признак уверенности"],["a primary source","первичный источник"],["a correction notice","уведомление об исправлении"]],"phrases":[["Fluent wording is not evidence that a claim is correct.","Беглая формулировка не доказывает правильность утверждения."],["The reference cannot be verified from the supplied information.","Ссылку невозможно проверить по предоставленным сведениям."],["If we had checked the source, we might have noticed the problem earlier.","Если бы мы проверили источник, мы могли бы заметить проблему раньше."],["Please distinguish a verified finding from a plausible explanation.","Пожалуйста, отличайте проверенный результат от правдоподобного объяснения."],["We should correct the record rather than merely soften the wording.","Следует исправить сведения, а не просто смягчить формулировку."]],"reading":{"title":"The confident answer with no evidence","paragraphs":["A researcher uses an AI assistant to prepare a short overview of a local education project. The assistant produces a fluent summary and attributes an impressive result to a report. When a colleague tries to locate the report, she discovers that the cited title cannot be found in the project's archive. The actual published evaluation measures attendance but does not support the claimed improvement in learning outcomes.","The researcher withdraws the unsupported sentence and replaces it with a narrower statement based on the available evaluation. She also records which source was checked and which claim remains unresolved. If the team had verified the citation before sharing the draft, it might have identified the error sooner. The incident does not establish that every AI-generated statement is wrong. It demonstrates why important claims should be checked against relevant primary evidence, regardless of how confidently they are phrased."],"questions":[["What was wrong with the AI summary?",["It was too short","The claimed result was unsupported by the available source","It contained no English"],1],["What did the actual evaluation measure?",["Attendance","All learning outcomes","The researcher's typing speed"],0],["How did the researcher correct the record?",["Kept the claim and added a stronger adjective","Deleted every source","Replaced the claim with a narrower verified statement"],2]]},"dialogue":[["Researcher","The assistant cited a report, but I can't find that title.","Ассистент сослался на отчёт, но я не могу найти такое название."],["Colleague","Does the actual evaluation support the claimed learning result?","Фактическая оценка подтверждает заявленный результат обучения?"],["Researcher","No. It measures attendance, not learning outcomes.","Нет. Она измеряет посещаемость, а не результаты обучения."],["Colleague","Then we need to correct the claim and state what remains unverified.","Тогда нужно исправить утверждение и указать, что осталось непроверенным."]],"listening":["What does the actual evaluation measure?",["Attendance","Learning outcomes","Both equally"],0],"speaking":["Explain why an apparently authoritative citation can still be unreliable.","Use a third conditional to describe a missed verification opportunity.","Give a short correction of an unsupported fictional claim without inventing a new source.","Compare evidence of attendance with evidence of educational improvement.","Present a balanced view of AI assistance that identifies one benefit and one verification requirement."],"writing":["Write a correction notice for a fictional report that contained an unsupported AI-generated claim.","Draft a verification checklist for a colleague reviewing a research summary.","Write a balanced argument about the role of AI in research, including a third-conditional reflection."],"model":"The previous draft attributed a learning improvement to an unverified report. The available evaluation supports an attendance finding only. We have removed the unsupported claim. If we had checked the citation earlier, we might have avoided the correction."}]);
